/**
 * Evaluates a mathematical expression containing +, -, *, / operators
 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Handle parentheses first
    while (expr.includes('(')) {
        const start = expr.lastIndexOf('(');
        const end = expr.indexOf(')', start);
        if (end === -1) {
            throw new Error('Mismatched parentheses');
        }
        const subExpr = expr.substring(start + 1, end);
        const result = evaluate(subExpr);
        expr = expr.substring(0, start) + result + expr.substring(end + 1);
    }

    // First, handle multiplication and division (left to right)
    let i = 0;
    while (i < expr.length) {
        if (expr[i] === '*' || expr[i] === '/') {
            const operator = expr[i];

            // Find the left operand (number before the operator)
            let leftStart = i - 1;
            while (leftStart >= 0 && /[0-9.]/.test(expr[leftStart])) {
                leftStart--;
            }
            leftStart++;
            const leftOperand = parseFloat(expr.substring(leftStart, i));

            // Find the right operand (number after the operator)
            let rightEnd = i + 1;
            while (rightEnd < expr.length && /[0-9.]/.test(expr[rightEnd])) {
                rightEnd++;
            }
            const rightOperand = parseFloat(expr.substring(i + 1, rightEnd));

            // Perform operation
