            if (operator === '*') {
                result = leftOperand * rightOperand;
            } else { // operator === '/'
                if (rightOperand === 0) {
                    throw new Error('Division by zero');
                }
                result = leftOperand / rightOperand;
            }

            // Replace the operation with result
            expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd);
            i = leftStart + result.toString().length;
        } else {
            i++;
        }
    }

    // Then, handle addition and subtraction (left to right)
    i = 0;
    while (i < expr.length) {
        if (expr[i] === '+' || expr[i] === '-') {
            // Skip if it's a negative number at the start
            if (i === 0 && expr[i] === '-') {
                i++;
                continue;
