// s5_expr.js - Expression evaluator with + - * / operations

/**
 * Evaluates a mathematical expression containing +, -, *, / operators
 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Handle parentheses first
    while (expr.includes('(')) {
        const start = expr.lastIndexOf('(');
        const end = expr.indexOf(')', start);
        if (end === -1) {
            throw new Error('Mismatched parentheses');
        }
        const subExpr = expr.substring(start + 1, end);
        const result = evaluate(subExpr);
        expr = expr.substring(0, start) + result + expr.substring(end + 1);
    }

    // Parse and evaluate multiplication and division first (left to right)
    const operators = ['*', '/'];
    for (const op of operators) {
        let i = 0;
        while (i < expr.length) {
            if (expr[i] === op) {
                // Find the left operand
                let leftStart = i - 1;
                while (leftStart >= 0 && /[0-9.]/.test(expr[leftStart])) {
                    leftStart--;
                }
                leftStart++;

                // Skip if it's a negative number
                if (leftStart === 0 && expr[leftStart] === '-') {
                    i++;
                    continue;
                }

                // Check if it's a negative sign (not an operator)
                if (leftStart > 0 && expr[leftStart - 1] === '(') {
                    // This is a negative number, skip it
                    i++;
                    continue;
                }

                const leftOperand = parseFloat(expr.substring(leftStart, i));

                // Find the right operand
                let rightEnd = i + 1;
                while (rightEnd < expr.length && /[0-9.]/.test(expr[rightEnd])) {
                    rightEnd++;
                }

                const rightOperand = parseFloat(expr.substring(i + 1, rightEnd));

                // Perform operation
                let result;
                if (op === '*') {
                    result = leftOperand * rightOperand;
                } else { // op === '/'
                    if (rightOperand === 0) {
                        throw new Error('Division by zero');
                    }
                    result = leftOperand / rightOperand;
                }

                // Replace the operation with result
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd);
                i = leftStart + result.toString().length;
            } else {
                i++;
            }
        }
    }

    // Parse and evaluate addition and subtraction (left to right)
    const operators2 = ['+', '-'];
    for (const op of operators2) {
        let i = 0;
        while (i < expr.length) {
            // Skip if it's a negative number at the start
            if (i === 0 && expr[i] === '-') {
                i++;
                continue;
            }

            // Skip if it's a negative sign (not an operator)
            if (i > 0 && expr[i] === '-' && (expr[i-1] === '+' || expr[i-1] === '-' || expr[i-1] === '*' || expr[i-1] === '/')) {
                i++;
                continue;
            }

            if (expr[i] === op) {
                // Find the left operand
                let leftStart = i - 1;
                while (leftStart >= 0 && /[0-9.]/.test(expr[leftStart])) {
                    leftStart--;
                }
                leftStart++;

                const leftOperand = parseFloat(expr.substring(leftStart, i));

                // Find the right operand
                let rightEnd = i + 1;
                while (rightEnd < expr.length && /[0-9.]/.test(expr[rightEnd])) {
                    rightEnd++;
                }

                const rightOperand = parseFloat(expr.substring(i + 1, rightEnd));

                // Perform operation
                let result;
                if (op === '+') {
                    result = leftOperand + rightOperand;
                } else { // op === '-'
                    result = leftOperand - rightOperand;
                }

                // Replace the operation with result
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd);
                i = leftStart + result.toString().length;
            } else {
                i++;
            }
        }
    }

    // At this point, expr should be a single number
    return parseFloat(expr);
}

// Test cases
try {
    // Basic operations
    console.assert(evaluate("1 + 2") === 3, "1 + 2 should equal 3");
    console.assert(evaluate("5 - 3") === 2, "5 - 3 should equal 2");
    console.assert(evaluate("4 * 6") === 24, "4 * 6 should equal 24");
    console.assert(evaluate("8 / 2") === 4, "8 / 2 should equal 4");

    // Precedence
    console.assert(evaluate("2 + 3 * 4") === 14, "2 + 3 * 4 should equal 14 (multiplication first)");
    console.assert(evaluate("10 - 6 / 2") === 7, "10 - 6 / 2 should equal 7 (division first)");

    // Left-to-right evaluation
    console.assert(evaluate("10 - 4 - 2") === 4, "10 - 4 - 2 should equal 4 (left to right)");
    console.assert(evaluate("12 / 3 / 2") === 2, "12 / 3 / 2 should equal 2 (left to right)");

    // With spaces
    console.assert(evaluate("  2 + 3  *  4  ") === 14, "Spaces should be ignored");

    // Decimals
    console.assert(evaluate("1.5 + 2.5") === 4, "1.5 + 2.5 should equal 4");
    console.assert(evaluate("7.5 / 2.5") === 3, "7.5 / 2.5 should equal 3");

    // Parentheses
    console.assert(evaluate("(2 + 3) * 4") === 20, "(2 + 3) * 4 should equal 20");
    console.assert(evaluate("2 * (3 + 4)") === 14, "2 * (3 + 4) should equal 14");

    // Complex expression
    console.assert(evaluate("2 + 3 * 4 - 1") === 13, "2 + 3 * 4 - 1 should equal 13");

    // Test division by zero
    try {
        evaluate("5 / 0");
        console.assert(false, "Should have thrown an error for division by zero");
    } catch (e) {
        console.assert(e.message === "Division by zero", "Should throw 'Division by zero' error");
    }

    // Test invalid characters
    try {
        evaluate("2 + 3 & 4");
        console.assert(false, "Should have thrown an error for invalid characters");
    } catch (e) {
        console.assert(e.message === "Invalid characters in expression", "Should throw 'Invalid characters in expression' error");
    }

    console.log("All tests passed!");
} catch (e) {
    console.error("Test failed:", e.message);
    process.exit(1);
}

module.exports = { evaluate };

